/* TRACE-X Investigator Console: self-contained browser UI, no CDN/network calls. */
'use strict';
const NAV=[['dashboard','▣','Dashboard'],['data','⬆','Data Intelligence'],['alerts','♟','Alerts'],['replay','▶','Replay & Trace'],['cases','▤','Cases'],['provenance','⇢','UTXO Provenance'],['graph','⌘','Transaction Graph'],['entities','⬡','Entities & Clusters'],['network','◇','Network Analysis'],['patterns','✣','Pattern Detection'],['risk','◉','Risk Analysis'],['search','⌕','Search'],['reports','▤','Reports'],['settings','⚙','Settings']];
const DEFAULTS={theme:'dark',neighbors:4,threshold:.8,critical:.5,labels:true};
const loadSettings=()=>{try{return {...DEFAULTS,...JSON.parse(localStorage.getItem('tracex-settings')||'{}')}}catch{return {...DEFAULTS}}};
let settings=loadSettings();
let state={data:null,source:'',route:'dashboard',entity:'',selectedNode:'',graphMode:'evidence',zoom:1,query:'',severity:'all',alertQuery:'',pattern:'all',ip:'',pathSource:'',pathTarget:'',pathResult:null,reportEntity:'',searchMode:'all',sort:'risk',error:'',replayFilter:'all',replayIndex:0,replaySpeed:1,replayPlaying:false};
const $=id=>document.getElementById(id), esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const attr=v=>esc(v); const num=v=>Number(v||0).toLocaleString('en-US'); const btc=v=>Number(v||0).toLocaleString('en-US',{maximumFractionDigits:5})+' BTC';
const short=(v,n=17)=>{v=String(v??'');return v.length>n?v.slice(0,Math.max(4,n-4))+'…'+v.slice(-3):v};
const A=()=>state.data?.alerts||[]; const P=()=>state.data?.risk_profiles||{};const M=()=>state.data?.ml_analysis?.transactions||[];const E=()=>state.data?.money_graph?.edges||[];
const asId=id=>String(id||'');const profile=id=>P()[id]||null;const alert=id=>A().find(a=>a.entity_id===id)||null;
const thresholdTag=(score)=>{let s=Number(score)||0;return s>=settings.critical?'CRITICAL':s>=.25?'HIGH':s>=.10?'MEDIUM':'LOW'};
const tag=(label)=>`<span class="badge ${label==='CRITICAL'?'critical':label==='HIGH'?'high':label==='MEDIUM'?'medium':'safe'}">${esc(label)}</span>`;
const link=(name,id)=>`<button class="btn btn-small btn-ghost" data-action="${attr(name)}" data-id="${attr(id)}">View →</button>`;
const card=(label,value,sub,color='')=>`<article class="metric"><div class="label">${esc(label)}</div><div class="num ${color}">${esc(value)}</div><div class="sub">${esc(sub)}</div></article>`;
const head=(title,subtitle,buttons='')=>`<div class="page-intro"><div><h1>${esc(title)}</h1><p>${esc(subtitle)}</p></div><div class="actions">${buttons}</div></div>`;
const panel=(title,content,right='')=>`<section class="panel"><div class="panel-head"><h2>${esc(title)}</h2>${right}</div>${content}</section>`;
const empty=(message='No matching records in this export.')=>`<div class="empty">${esc(message)}</div>`;
function toast(message){const t=$('toast');t.textContent=message;t.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.classList.remove('show'),3000)}
function save(){localStorage.setItem('tracex-settings',JSON.stringify(settings));document.body.classList.toggle('light',settings.theme==='light')}
function navigate(route){if(route!=='replay')v5Stop();const hash='#'+route;if(location.hash!==hash)location.hash=hash;else render();}
function pickedEntity(id,route='graph'){if(!profile(id)&&!alert(id)){toast('Entity not found in this export');return}state.entity=id;state.selectedNode=id;state.zoom=1;navigate(route)}
function navRender(){const nav=$('sidebarNav');nav.innerHTML=NAV.map(([id,ic,title])=>`<button class="nav-link ${id===state.route?'active':''}" data-action="nav" data-id="${id}" aria-current="${id===state.route?'page':'false'}"><span class="nav-icon" aria-hidden="true">${ic}</span><span>${title}</span></button>`).join('');$('pageTitle').textContent=NAV.find(n=>n[0]===state.route)?.[2]||'Dashboard';}
async function loadData(notify=false){
 let got=null,src='',server=false;
 // Netlify public preview: only precomputed, synthetic browser-served JSON files.
 try{src=window.TRACEX_STATIC_DATASET==='legacy'?'demo_2008_dashboard_data.json':'demo_dashboard_data.json';
     const r=await fetch(src+'?t='+Date.now(),{cache:'no-store'});if(!r.ok)throw Error('Demo data file missing: '+src);got=await r.json();
 }catch(err){state.error=err.message;}
 if(!got||!got.summary||!Array.isArray(got.alerts)||!got.risk_profiles||!got.money_graph){state.data=null;$('dataBanner').textContent='No usable data. Start the v7 local server, upload and analyze a dataset.';render();return}
 let changed=state.source!==src;
 state.data=got;state.source=src;
 if(changed){v5Stop();state.entity='';state.selectedNode='';state.ip='';state.pathResult=null;state.query='';state.replayIndex=0;state.caseTx='';}
 state.entity=profile(state.entity)?state.entity:(A()[0]?.entity_id||Object.keys(P())[0]||'');state.selectedNode=state.entity;
 state.reportEntity=profile(state.reportEntity)?state.reportEntity:state.entity;state.pathSource=profile(state.pathSource)?state.pathSource:state.entity;
 state.pathTarget=profile(state.pathTarget)?state.pathTarget:Object.keys(P()).find(x=>x!==state.pathSource)||'';
 $('dataBanner').innerHTML='<strong>PUBLIC SYNTHETIC DEMO</strong> · '+esc(got.dataset?.filename||'Bundled records')+' · '+num(got.summary.total_transactions)+' precomputed transactions · Data import and ML processing require the local WSL backend. Not live criminal intelligence.';
 render();void v6LoadProvenance();if(notify)toast('Active dataset view refreshed');
}
function render(){state.route=decodeURIComponent((location.hash||'#dashboard').slice(1).split('?')[0]);if(!NAV.find(n=>n[0]===state.route))state.route='dashboard';navRender();if(!state.data){$('app').innerHTML=empty('The dashboard is waiting for a local JSON export.');return}const r={dashboard:dashboardPage,alerts:alertsPage,replay:replayPage,cases:casesPage,provenance:provenancePage,graph:graphPage,entities:entitiesPage,network:networkPage,patterns:patternPage,risk:riskPage,search:searchPage,reports:reportsPage,settings:settingsPage,data:v7DataPage,graph3d:window.traceX3DPage}[state.route];$('app').innerHTML=r();save();if(state.route==='graph3d')window.traceX3DMount?.();else window.traceX3DStop?.();}
function alertTable(items=A(),limit=15){if(!items.length)return empty();return `<div class="table-scroll"><table><thead><tr><th>Rank</th><th>Entity</th><th>Composite score</th><th>Severity</th><th>Pattern evidence</th><th>Actions</th></tr></thead><tbody>${items.slice(0,limit).map(a=>`<tr class="data-row" data-action="open-alert" data-id="${attr(a.entity_id)}"><td>#${num(a.rank)}</td><td class="mono">${esc(a.entity_id)}</td><td>${Number(a.composite_score).toFixed(3)}</td><td>${tag(thresholdTag(a.composite_score))}</td><td class="small">${esc(Object.entries(a.pattern_hits||{}).filter(([_,v])=>v?.length).map(([k,v])=>`${k.replaceAll('_',' ')} (${v.length})`).join(', ')||'No structural hit')}</td><td>${link('open-alert',a.entity_id)}</td></tr>`).join('')}</tbody></table></div>`}
function barChart(data,countKey='count',labelKey='hour'){const max=Math.max(1,...data.map(x=>Number(x[countKey])||0));return `<div class="chart-bars" role="img" aria-label="Distribution: ${data.map(x=>x[labelKey]+': '+x[countKey]).join(', ')}">${data.map(x=>`<span style="height:${Math.max(2,(Number(x[countKey])/max)*100)}%" title="${attr(x[labelKey])}: ${num(x[countKey])}"></span>`).join('')}</div>`}
function miniBreakdown(a){if(!a)return empty('Select an alert to inspect its score factors.');return `<div class="explain">${(a.score_breakdown||[]).map(f=>`<div class="factor"><div><span>${esc(f.feature.replaceAll('_',' '))}</span><strong>${Number(f.contribution).toFixed(3)} / ${Number(f.weight).toFixed(2)}</strong></div><div class="bar"><span style="width:${Math.max(0,Math.min(100,Number(f.normalized_value)*100))}%"></span></div></div>`).join('')}</div><p class="panel-note">Contributions are normalized rule/ML score components. They are not probability or SHAP values.</p>`}
function heroMetrics(){const d=state.data;const high=M().filter(t=>Number(t.anomaly_score)>=settings.threshold).length;const boxes=[
 ['⬡','Total Transactions',num(d.summary.total_transactions),state.data?.dataset?.model?.mode==='unavailable'?'Parsed; ML unavailable':'Parsed and scored','blue','graph'],
 ['♧','Wallet Addresses',num(d.summary.total_wallets_involved),'Observed in data','green','entities'],
 ['◈','Entity Clusters',num(d.summary.total_entities_scanned),'Inferred groups','cyan','entities'],
 ['⚑','Ranked Alerts',num(A().length),'Open investigations','red','alerts'],
 ['⌁','ML Outliers',num(high),'Score ≥ '+settings.threshold,'orange','risk']];
 return `<div class="hero-metrics">${boxes.map(([icon,label,value,sub,color,route])=>`<button class="hero-metric" data-action="nav" data-id="${route}"><span class="hero-icon ${color}">${icon}</span><span><span class="hero-label">${esc(label)}</span><strong>${value}</strong><small>${esc(sub)}</small></span></button>`).join('')}</div>`}
function alertMini(){return `<div class="table-scroll"><table class="mini-table"><thead><tr><th>#</th><th>Entity / Cluster</th><th>Score</th><th>Evidence</th></tr></thead><tbody>${A().slice(0,5).map(a=>`<tr class="data-row" data-action="open-alert" data-id="${attr(a.entity_id)}"><td>${a.rank}</td><td class="mono">${esc(a.entity_id)}</td><td>${tag(thresholdTag(a.composite_score))} ${Number(a.composite_score).toFixed(3)}</td><td>${esc(Object.entries(a.pattern_hits||{}).filter(([k,v])=>v?.length).map(([k,v])=>k.replaceAll('_',' ')+' ('+v.length+')').join(', ')||'Model / graph signals')}</td></tr>`).join('')}</tbody></table></div>`}
function patternMini(){const types=['peeling_chain','fan_out','consolidation'];const names={peeling_chain:'Peeling chain',fan_out:'Fan-out',consolidation:'Consolidation'};return `<div class="table-scroll"><table class="mini-table"><thead><tr><th>Pattern</th><th>TXIDs</th><th>Open</th></tr></thead><tbody>${types.map(t=>`<tr class="data-row" data-action="nav" data-id="patterns"><td>${names[t]}</td><td>${new Set(A().flatMap(a=>a.pattern_hits?.[t]||[])).size}</td><td>→</td></tr>`).join('')}</tbody></table></div><p class="panel-note">Counts represent distinct exported transaction IDs. Not criminal classifications.</p>`}
function riskMini(){const bins=[0,0,0];for(const a of A()){let score=Number(a.composite_score)||0;bins[score>=settings.critical?0:score>=.25?1:2]++}const count=A().length||1,red=bins[0]/count*100,amber=(bins[0]+bins[1])/count*100;const donut=`background:conic-gradient(#ff6374 0 ${red}%,#ffb94f ${red}% ${amber}%,#37d8a6 ${amber}% 100%)`;return `<div class="risk-mini"><div class="donut" style="${donut}"><span><b>${A().length}</b><small>alerts</small></span></div><div class="risk-keys"><div><i style="background:#ff6374"></i>Critical <b>${bins[0]}</b></div><div><i style="background:#ffb94f"></i>High <b>${bins[1]}</b></div><div><i style="background:#37d8a6"></i>Other <b>${bins[2]}</b></div></div></div><p class="panel-note">UI score buckets, not validated probability bands.</p>`}
/* dashboardPage replaced by TRACE-X v4 evidence-led implementation. */
function entityDetail(id,compact=false){const p=profile(id),a=alert(id);if(!p)return empty('No entity profile found.');const fields=[['Entity ID',id],['Composite score',a?Number(a.composite_score).toFixed(4):'Not top-ranked'],['Incoming (approx.)',btc(p.incoming_total)],['Outgoing (approx.)',btc(p.outgoing_total)],['Primary observed IP',p.device_ip||'Unavailable'],['Observed countries',(p.countries||[]).join(', ')||'Unknown'],['Counterparties',num(p.n_unique_counterparties)]];return `<div class="form-row" style="justify-content:space-between;margin-bottom:13px"><strong class="mono">${esc(id)}</strong>${tag(a?thresholdTag(a.composite_score):'NOT RANKED')}</div><dl class="details">${(compact?fields.slice(0,5):fields).map(([k,v])=>`<dt>${esc(k)}</dt><dd>${esc(v)}</dd>`).join('')}</dl>${!compact?`<div class="section-gap">${panel('Risk score components',miniBreakdown(a))}</div><div class="section-gap"><h3>Investigative flags</h3>${(p.suspicion_flags||[]).map(f=>`<p class="panel-note">• ${esc(f)}</p>`).join('')}</div>`:''}<div class="actions section-gap"><button class="btn btn-small" data-action="focus-graph" data-id="${attr(id)}">Open graph →</button><button class="btn btn-small" data-action="open-report" data-id="${attr(id)}">Case brief →</button></div>`}
/* alertsPage replaced by TRACE-X v4 evidence-led implementation. */
function getFlow(id){const incoming=E().filter(e=>e.to===id&&e.from!==id).sort((a,b)=>b.total_amount-a.total_amount).slice(0,settings.neighbors);const outgoing=E().filter(e=>e.from===id&&e.to!==id).sort((a,b)=>b.total_amount-a.total_amount).slice(0,settings.neighbors);return {incoming,outgoing}}
function pos(i,n,x){return {x,y: n<=1?205:60+i*(290/(n-1))}}
function svgNode(id,x,y,color,sub='',selected=false){const title=esc(id+(sub?' · '+sub:''));return `<g class="graph-node" data-action="graph-node" data-id="${attr(id)}" role="button" tabindex="0" aria-label="Inspect ${title}"><title>${title}</title><rect x="${x-62}" y="${y-19}" width="124" height="38" rx="9" fill="${color}" stroke="${selected?'#fff':'#6d99c0'}" stroke-width="${selected?2:1}"/>${settings.labels?`<text x="${x}" y="${y+4}" text-anchor="middle" fill="#f7fbff" font-size="10.5" font-weight="700">${esc(short(id,18))}</text>`:''}</g>`}
function flowSvg(id){const {incoming,outgoing}=getFlow(id);let nodes='',edges='',labels='';const cx=480,cy=205;
 incoming.forEach((e,i)=>{const {x,y}=pos(i,incoming.length,120);const active=state.selectedNode===e.from;nodes+=svgNode(e.from,x,y,active?'#9c4150':'#215079',btc(e.total_amount),active);edges+=`<path d="M ${x+63} ${y} C 295 ${y}, 320 ${cy}, ${cx-66} ${cy}" fill="none" stroke="#4795c9" stroke-width="${Math.min(4,1.2+Number(e.tx_count||0)*.14)}" marker-end="url(#arrow)"/>`;labels+=`<text x="270" y="${y<cy?y+15:y-12}" text-anchor="middle" fill="#add6f5" font-size="9">${esc(short(btc(e.total_amount),15))}</text>`});
 outgoing.forEach((e,i)=>{const {x,y}=pos(i,outgoing.length,850);const active=state.selectedNode===e.to;nodes+=svgNode(e.to,x,y,active?'#9c4150':'#215079',btc(e.total_amount),active);edges+=`<path d="M ${cx+67} ${cy} C 650 ${cy}, 675 ${y}, ${x-65} ${y}" fill="none" stroke="#50a4b7" stroke-width="${Math.min(4,1.2+Number(e.tx_count||0)*.14)}" marker-end="url(#arrow)"/>`;labels+=`<text x="690" y="${y<cy?y+15:y-12}" text-anchor="middle" fill="#add6f5" font-size="9">${esc(short(btc(e.total_amount),15))}</text>`});
 nodes+=svgNode(id,cx,cy,'#aa3e52','Focused entity',true);
 return `<svg viewBox="0 0 970 410" xmlns="http://www.w3.org/2000/svg" aria-label="Incoming entities left, focused entity center, outgoing entities right"><defs><marker id="arrow" markerWidth="9" markerHeight="9" refX="7" refY="4.5" orient="auto" markerUnits="userSpaceOnUse"><path d="M0,0 L9,4.5 L0,9 z" fill="#72c5fa"/></marker></defs><g transform="translate(${(1-state.zoom)*480} ${(1-state.zoom)*205}) scale(${state.zoom})"><text x="120" y="27" fill="#80b6dd" font-size="13" text-anchor="middle">INCOMING</text><text x="480" y="27" fill="#eab3ba" font-size="13" text-anchor="middle">FOCUS</text><text x="850" y="27" fill="#80b6dd" font-size="13" text-anchor="middle">OUTGOING</text>${edges}${labels}${nodes}${incoming.length?'':`<text x="120" y="230" fill="#aac7dc" text-anchor="middle" font-size="11">No incoming links</text>`}${outgoing.length?'':`<text x="850" y="230" fill="#aac7dc" text-anchor="middle" font-size="11">No outgoing links</text>`}</g></svg>`}
function layeredSvg(id){
 const neighbor=Math.max(2,Math.min(6,settings.neighbors));
 const all=E().filter(e=>e.from!==e.to&&Number(e.total_amount)>0);
 const rank=(arr)=>arr.sort((a,b)=>Number(b.total_amount)-Number(a.total_amount));
 const used=new Set([id]);
 const ups=rank(all.filter(e=>e.to===id)).map(e=>e.from).filter(x=>{if(used.has(x))return false;used.add(x);return true}).slice(0,neighbor);
 const downs=rank(all.filter(e=>e.from===id)).map(e=>e.to).filter(x=>{if(used.has(x))return false;used.add(x);return true}).slice(0,neighbor);
 const candidateUp=rank(all.filter(e=>ups.includes(e.to)&&!used.has(e.from)));const up2=[];for(const e of candidateUp){if(!used.has(e.from)){used.add(e.from);up2.push(e.from)}if(up2.length>=3)break}
 const candidateDown=rank(all.filter(e=>downs.includes(e.from)&&!used.has(e.to)));const down2=[];for(const e of candidateDown){if(!used.has(e.to)){used.add(e.to);down2.push(e.to)}if(down2.length>=3)break}
 const tiers=[up2,ups,[id],downs,down2],labels=[['2-HOP UPSTREAM','Earlier observed senders'],['DIRECT SENDERS','One hop before focus'],['FOCUSED ENTITY','Currently investigated'],['DIRECT RECEIVERS','One hop after focus'],['2-HOP DOWNSTREAM','Later observed receivers']];
 const ypos=[91,204,317,430,543],colors=['#e45770','#f5b34e','#3c9cf0','#a176f9','#35cd9d'];
 const positions=new Map();let nodes='',connections='',amountLabels='';
 tiers.forEach((ids,layer)=>ids.forEach((node,i)=>{const x=ids.length===1?570:158+i*(824/Math.max(1,ids.length-1));positions.set(node,{x,y:ypos[layer],layer});}));
 const focused=state.selectedNode&&positions.has(state.selectedNode)?state.selectedNode:id;
 const links=all.filter(e=>{let a=positions.get(e.from),b=positions.get(e.to);return a&&b&&b.layer===a.layer+1});
 const topLabels=new Set(rank(links.filter(e=>e.from===id||e.to===id)).slice(0,5));
 const strongest=Math.max(1,...links.map(e=>Number(e.total_amount)));
 const activePath=Array.isArray(state.pathResult)?new Set(state.pathResult.slice(0,-1).map((n,i)=>n+'→'+state.pathResult[i+1])):new Set();
 links.forEach(e=>{const a=positions.get(e.from),b=positions.get(e.to);const selected=focused===e.from||focused===e.to;const traced=activePath.has(e.from+'→'+e.to);const color=traced?'#ff6374':selected?'#79caff':'#487195';const y1=a.y+22,y2=b.y-22;connections+=`<path d="M${a.x} ${y1} C${a.x} ${(y1+y2)/2},${b.x} ${(y1+y2)/2},${b.x} ${y2}" fill="none" stroke="${color}" stroke-width="${(1+2.6*Math.sqrt(Number(e.total_amount)/strongest)).toFixed(2)}" stroke-opacity="${traced||selected?'.96':'.64'}" marker-end="url(#layer-arrow)"><title>${esc(e.from)} → ${esc(e.to)} · ${btc(e.total_amount)} · ${num(e.tx_count)} transaction(s) · sample ${esc(e.sample_txid||'—')}</title></path>`;
 if(topLabels.has(e))amountLabels+=`<g><rect x="${(a.x+b.x)/2-28}" y="${(y1+y2)/2-9}" width="56" height="17" rx="5" fill="#112336" stroke="#35536b"/><text x="${(a.x+b.x)/2}" y="${(y1+y2)/2+3}" text-anchor="middle" fill="#d1edff" font-size="9">${Number(e.total_amount).toFixed(2)} BTC</text></g>`;
 });
 tiers.forEach((ids,layer)=>ids.forEach((node)=>{const at=positions.get(node),a=alert(node),current=node===focused,main=node===id;const fill=main?'#195c9b':a&&Number(a.composite_score)>=settings.critical?'#723848':'#153c55';const stroke=current?'#e8f8ff':colors[layer];nodes+=`<g class="graph-node layered-node" role="button" tabindex="0" data-action="graph-node" data-id="${attr(node)}" aria-label="Inspect ${attr(node)}"><title>${esc(node)}${a?' · score '+Number(a.composite_score).toFixed(3):''}</title><circle cx="${at.x}" cy="${at.y}" r="${main?26:23}" fill="${fill}" stroke="${stroke}" stroke-width="${current?3:2}"/><text x="${at.x}" y="${at.y+4}" text-anchor="middle" fill="#e8f7ff" font-size="${main?16:13}">${main?'◎':layer===0?'◈':layer===4?'◆':'⬡'}</text>${settings.labels?`<text x="${at.x}" y="${at.y+42}" fill="#e7f1fa" text-anchor="middle" font-size="11" font-weight="700">${esc(short(node,17))}</text>`:''}${a?`<circle cx="${at.x+19}" cy="${at.y-19}" r="4.5" fill="#ff6374"/>`:''}</g>`}));
 const stripes=tiers.map((ids,i)=>`<rect x="7" y="${ypos[i]-49}" width="1126" height="97" rx="5" fill="${colors[i]}" fill-opacity=".075" stroke="${colors[i]}" stroke-opacity=".17"/><rect x="7" y="${ypos[i]-49}" width="4" height="97" rx="2" fill="${colors[i]}"/><text x="20" y="${ypos[i]-29}" fill="${colors[i]}" font-size="12" font-weight="750">${labels[i][0]}</text><text x="20" y="${ypos[i]-14}" fill="#a9bed0" font-size="9">${labels[i][1]} · ${ids.length} node(s)</text>`).join('');
 return `<svg viewBox="0 0 1140 596" xmlns="http://www.w3.org/2000/svg" aria-label="Five layered graph of the focused entity and its real first and second hop inferred transfers"><defs><marker id="layer-arrow" markerWidth="7" markerHeight="7" refX="6" refY="3.5" orient="auto" markerUnits="userSpaceOnUse"><path d="M0 0 L7 3.5 L0 7 Z" fill="#79bbf2"/></marker></defs><g transform="translate(${(1-state.zoom)*570} ${(1-state.zoom)*298}) scale(${state.zoom})">${stripes}${connections}${amountLabels}${nodes}</g></svg>`
}
function evidenceSvg(id){const a=alert(id);if(!a)return `<div class="empty">Wallet evidence is included for the 15 exported alerts. Select a ranked entity to view its sampled wallet graph.</div>`;const raw=a.graph?.tx_edges||[];const ordered=raw.slice(0,Math.max(5,settings.neighbors*2));if(!ordered.length)return empty('No wallet-to-wallet edges in this evidence sample.');const walletIds=[...new Set(ordered.flatMap(e=>[e.source,e.target]))];const targetSet=new Set(ordered.map(e=>e.target));const sources=walletIds.filter(w=>!targetSet.has(w)).slice(0,6);const left=sources.length?sources:walletIds.slice(0,Math.ceil(walletIds.length/2));const right=walletIds.filter(w=>!left.includes(w)).slice(0,6);let edges='',nodes='';const layout=new Map();left.forEach((w,i)=>layout.set(w,pos(i,left.length,180)));right.forEach((w,i)=>layout.set(w,pos(i,right.length,785)));ordered.forEach(e=>{let s=layout.get(e.source),t=layout.get(e.target);if(s&&t){edges+=`<path d="M${s.x+63},${s.y} L${t.x-63},${t.y}" fill="none" stroke="#4795c9" stroke-width="1.5" marker-end="url(#e-arrow)"><title>${esc(e.txid)} · ${esc(btc(e.amount))}</title></path>`}});for(const [w,v]of layout)nodes+=svgNode(w,v.x,v.y,(a.graph.wallet_nodes||[]).find(n=>n.id===w)?.is_entity_wallet?'#245e83':'#744d3f',w,state.selectedNode===w);return `<svg viewBox="0 0 970 410" xmlns="http://www.w3.org/2000/svg"><defs><marker id="e-arrow" markerWidth="8" markerHeight="8" refX="7" refY="4" orient="auto"><path d="M0,0 L8,4 L0,8 z" fill="#72c5fa"/></marker></defs><g transform="translate(${(1-state.zoom)*480} ${(1-state.zoom)*205}) scale(${state.zoom})"><text x="180" y="27" fill="#80b6dd" font-size="12" text-anchor="middle">SOURCE WALLETS</text><text x="785" y="27" fill="#80b6dd" font-size="12" text-anchor="middle">DESTINATION WALLETS</text>${edges}${nodes}</g></svg>`}
function graphLayout(id,compact=false){const controls=`<div class="graph-toolbar"><div class="legend"><span><b style="background:#e45770"></b>Upstream</span><span><b style="background:#3c9cf0"></b>Focus</span><span><b style="background:#a176f9"></b>Receivers</span><span><b style="background:#35cd9d"></b>Downstream</span><span>Arrows = inferred flow</span></div>${compact?'':`<div class="zoom-controls"><button class="btn btn-small" data-action="zoom-out">−</button><button class="btn btn-small" data-action="zoom-reset">Fit</button><button class="btn btn-small" data-action="zoom-in">+</button><button class="btn btn-small" data-action="fullscreen-graph">⛶</button></div>`}</div>`;
 return controls+`<div class="graph-canvas ${state.graphMode==='layered'?'layered-canvas':''}">${state.graphMode==='evidence'?evidenceSvg(id):state.graphMode==='flow'?flowSvg(id):layeredSvg(id)}<div class="graph-help">${state.graphMode==='layered'?'Five actual hop-distance tiers · Click a node to refocus · Arrow hover reveals BTC and sample TXID.':state.graphMode==='evidence'?'Sampled wallet evidence · Click a wallet to inspect it.':'Direct in/out entity edges · Click a node to investigate.'}</div></div><p class="panel-note">Inferred entity links are not UTXO-accurate provenance. Layer positions describe observed hop distance, not verified criminal or service roles.</p>${compact?'':`<div class="note">Showing a focused neighborhood of ${num(E().length)} aggregated edges. Use the entity selector or path tracer for other cases.</div>`}`}

function tracePath(src,dst){if(!src||!dst||src===dst)return src===dst?[src]:null;const adj=new Map();for(const e of E()){if(!adj.has(e.from))adj.set(e.from,[]);adj.get(e.from).push(e.to)}const queue=[[src]],visited=new Set([src]);for(let h=0;h<queue.length&&h<4000;h++){const p=queue[h];if(p.length>6)continue;for(const v of adj.get(p.at(-1))||[]){if(v===dst)return [...p,v];if(!visited.has(v)){visited.add(v);queue.push([...p,v])}}}return null}
function optionsEntities(selected){return Object.keys(P()).sort().map(id=>`<option value="${attr(id)}" ${selected===id?'selected':''}>${esc(id)}</option>`).join('')}
