function entitiesPage(){let rows=Object.entries(P()).map(([id,p])=>({id,p,a:alert(id)}));rows.sort((x,y)=>state.sort==='name'?x.id.localeCompare(y.id):(y.a?.composite_score||0)-(x.a?.composite_score||0));let q=state.query.toLowerCase();rows=rows.filter(x=>!q||x.id.toLowerCase().includes(q)||String(x.p.device_ip||'').includes(q)||x.p.countries?.join(' ').toLowerCase().includes(q));return head('Entities & clusters','Browse every inferred wallet group. An entity cluster is an analytical hypothesis, not a verified legal identity.')+`<div class="panel-row">${panel('Entity directory',`<div class="form-row"><label class="field">Find entity, IP or country<input id="entityQuery" class="input" value="${attr(state.query)}" placeholder="cluster_… / IP / US"></label><label class="field">Sort<select id="entitySort" class="select"><option value="risk" ${state.sort==='risk'?'selected':''}>Composite score</option><option value="name" ${state.sort==='name'?'selected':''}>Entity ID</option></select></label></div><p class="panel-note">${rows.length} matching clusters</p><div class="table-scroll"><table><thead><tr><th>Entity</th><th>Risk category</th><th>Observed IP</th><th>Counterparties</th><th>Investigate</th></tr></thead><tbody>${rows.slice(0,100).map(x=>`<tr class="data-row" data-action="select-entity" data-id="${attr(x.id)}"><td class="mono">${esc(x.id)}</td><td>${tag(x.a?thresholdTag(x.a.composite_score):'NOT RANKED')}</td><td class="mono">${esc(x.p.device_ip||'—')}</td><td>${num(x.p.n_unique_counterparties)}</td><td>${link('select-entity',x.id)}</td></tr>`).join('')}</tbody></table></div>`)}${panel('Cluster profile',entityDetail(state.entity))}</div>`}
function networkRows(){const map=new Map();for(const e of state.data.intelligence?.entity_ip_edges||[]){if(!map.has(e.ip))map.set(e.ip,new Set());map.get(e.ip).add(e.entity_id)}return [...map].map(([ip,entities])=>({ip,entities:[...entities]})).sort((a,b)=>b.entities.length-a.entities.length||a.ip.localeCompare(b.ip))}
function networkPage(){const rows=networkRows();const selected=rows.find(x=>x.ip===state.ip)||rows[0];return head('Network analysis','Correlate observed source IPs with wallet-entity hypotheses. Shared relay IPs are evidence, not proof of joint ownership.')+`<div class="metrics">${card('Observed IP addresses',num(rows.length),'From transaction broadcasts')}${card('Shared IPs',num(rows.filter(r=>r.entities.length>1).length),'May reflect relay infrastructure')}${card('Entity–IP observations',num(state.data.intelligence?.entity_ip_edges?.length),'Unique observed associations')}${card('Countries represented',num(state.data.filters?.countries?.length),'Available geo annotations')}</div><div class="panel-row">${panel('IP observation list',`<div class="table-scroll"><table><thead><tr><th>IP address</th><th>Linked clusters</th><th>Interpretation</th></tr></thead><tbody>${rows.map(r=>`<tr class="data-row" data-action="select-ip" data-id="${attr(r.ip)}"><td class="mono">${esc(r.ip)}</td><td>${r.entities.length}</td><td>${r.entities.length>1?tag('SHARED IP'):tag('SINGLE CLUSTER')}</td></tr>`).join('')}</tbody></table></div>`)}${panel('IP inspector',selected?`<h3 class="mono">${esc(selected.ip)}</h3><p class="panel-note">Observed with ${selected.entities.length} cluster(s). A relay, NAT, or shared service could produce this association.</p><h3 class="section-gap">Associated entities</h3>${selected.entities.map(id=>`<div class="list-card"><div class="line"><span class="mono">${esc(id)}</span>${link('focus-graph',id)}</div></div>`).join('')}`:empty())}</div>`}
function patternPage(){const types=['peeling_chain','fan_out','consolidation'];const names={peeling_chain:'Peeling chain',fan_out:'Fan-out',consolidation:'Consolidation'};const counts=Object.fromEntries(types.map(t=>[t,new Set(A().flatMap(a=>a.pattern_hits?.[t]||[])).size]));const selected=A().filter(a=>state.pattern==='all'||(a.pattern_hits?.[state.pattern]||[]).length);return head('Pattern detection','Review structural transaction patterns supported by the current engine. These signatures are not independently verified criminal typologies.')+`<div class="threecol">${types.map(t=>card(names[t],counts[t],'Unique flagged TXIDs')).join('')}</div><div class="panel section-gap"><div class="panel-head"><h2>Detected pattern evidence</h2><select class="select" id="patternFilter"><option value="all">All patterns</option>${types.map(t=>`<option value="${t}" ${state.pattern===t?'selected':''}>${names[t]}</option>`).join('')}</select></div>${selected.map(a=>{const hits=Object.entries(a.pattern_hits||{}).filter(([k,v])=>v?.length&&(state.pattern==='all'||state.pattern===k));if(!hits.length)return '';return `<div class="list-card"><div class="line"><strong class="mono">${esc(a.entity_id)}</strong>${link('focus-graph',a.entity_id)}</div>${hits.map(([k,ids])=>`<p class="panel-note"><strong>${esc(names[k]||k)}:</strong> ${ids.map(id=>`<button class="btn btn-small" data-action="find-tx" data-id="${attr(id)}">${esc(id)}</button>`).join(' ')}</p>`).join('')}</div>`}).join('')||empty('No matching structural patterns.')}<p class="panel-note">Only peeling-chain, fan-out and consolidation detectors are implemented in the supplied backend. CoinJoin classification is not implied by this view.</p></div>`}
function riskPage(){const selected=alert(state.entity)||A()[0];const hi=M().filter(t=>t.anomaly_score>=settings.threshold).sort((a,b)=>b.anomaly_score-a.anomaly_score);let bins=Array.from({length:10},()=>0);for(const t of M()){bins[Math.min(9,Math.floor(Math.max(0,Number(t.anomaly_score)||0)*10))]++}return head('Risk analysis','Disentangle the ML outlier score from graph heuristics and relative composite rankings.',`<button class="btn" data-action="csv">↓ Export alerts CSV</button>`)+`<div class="metrics">${card('Scored transactions',num(state.data?.dataset?.model?.mode==='unavailable'?0:M().length),'ML ensemble (when available)')}${card('Outliers above threshold',num(hi.length),`≥ ${settings.threshold} anomaly score`,'red')}${card('Ranked alert groups',num(A().length),'Exported top entities')}${card('Risk components',state.data?.dataset?'2 active':'4','Patterns · ML; independent seeds not configured')}</div><div class="twocol">${panel('ML outlier score distribution',`${barChart(bins.map((count,i)=>({bucket:(i/10).toFixed(1),count})), 'count','bucket')}<p class="panel-note">Bins 0.0–0.9; higher values are relatively more unusual. The ensemble score is not a fraud probability.</p>`)}${panel('Selected entity breakdown',`<label class="field">Inspect ranked entity<select class="select" id="riskEntity">${A().map(a=>`<option value="${attr(a.entity_id)}" ${state.entity===a.entity_id?'selected':''}>${esc(a.entity_id)}</option>`).join('')}</select></label><p class="panel-note">Composite: ${selected?Number(selected.composite_score).toFixed(4):'—'} · ${selected?thresholdTag(selected.composite_score):'—'}</p>${miniBreakdown(selected)}`)}</div><div class="section-gap">${panel('Highest-scoring transactions',`<div class="table-scroll"><table><thead><tr><th>TXID</th><th>Outlier score</th><th>Isolation Forest</th><th>Reconstruction network</th><th>Entity</th></tr></thead><tbody>${hi.slice(0,50).map(t=>`<tr class="data-row" data-action="find-tx" data-id="${attr(t.txid)}"><td class="mono">${esc(t.txid)}</td><td>${Number(t.anomaly_score).toFixed(3)}</td><td>${Number(t.iso_score).toFixed(3)}</td><td>${Number(t.ae_score).toFixed(3)}</td><td class="mono">${esc(t.entity_id||'—')}</td></tr>`).join('')}</tbody></table></div>${!hi.length?empty('No transactions above the selected threshold.'):''}`)}</div>`}
function findResults(){const q=state.query.trim().toLowerCase();if(!q)return {entities:[],ips:[],txs:[]};const entities=Object.entries(P()).filter(([id,p])=>(state.searchMode==='all'||state.searchMode==='entities')&&(id.toLowerCase().includes(q)||String(p.device_ip||'').includes(q))).slice(0,50);const ips=networkRows().filter(r=>(state.searchMode==='all'||state.searchMode==='ips')&&r.ip.includes(q)).slice(0,30);const txs=M().filter(t=>(state.searchMode==='all'||state.searchMode==='transactions')&&(String(t.txid).toLowerCase().includes(q)||t.from_wallets?.some(w=>w.toLowerCase().includes(q))||t.to_wallets?.some(w=>w.toLowerCase().includes(q))||String(t.entity_id).toLowerCase().includes(q))).slice(0,50);return {entities,ips,txs}}
function searchPage(){const {entities,ips,txs}=findResults();return head('Search evidence','Search the current local export for entity IDs, Bitcoin addresses, IPs, or transaction IDs.')+`<section class="panel"><form id="searchForm" class="form-row"><label class="field">Search text<input id="searchQuery" class="input" value="${attr(state.query)}" placeholder="tx002000 / cluster_0022 / wallet…" autocomplete="off"></label><label class="field">Dataset<select id="searchMode" class="select">${[['all','Active dataset'],['entities','Entities'],['transactions','Transactions'],['ips','IP observations']].map(([v,n])=>`<option value="${v}" ${state.searchMode===v?'selected':''}>${n}</option>`).join('')}</select></label><button class="btn btn-primary" type="submit">Search →</button></form></section>${!state.query.trim()?`<div class="section-gap">${empty('Enter a search value above. Try tx002000 or cluster_0022 for the included synthetic demo.')}</div>`:`<div class="section-gap">${panel(`Entity matches (${entities.length})`,entities.length?entities.map(([id,p])=>`<div class="list-card"><div class="line"><span class="mono">${esc(id)}</span>${link('focus-graph',id)}</div><p class="panel-note">IP ${esc(p.device_ip||'—')} · ${num(p.n_unique_counterparties)} counterparties</p></div>`).join(''):empty())}</div><div class="section-gap">${panel(`Transaction matches (${txs.length})`,txs.length?txs.map(t=>`<div class="list-card"><div class="line"><strong class="mono">${esc(t.txid)}</strong><span>${Number(t.anomaly_score).toFixed(3)} anomaly</span></div><p class="panel-note">${esc(t.timestamp)} · ${esc(btc(t.amount))}</p><p class="panel-note">FROM: <span class="mono">${esc((t.from_wallets||[]).join(', '))}</span></p><p class="panel-note">TO: <span class="mono">${esc((t.to_wallets||[]).join(', '))}</span></p>${t.entity_id?link('focus-graph',t.entity_id):''}</div>`).join(''):empty())}</div><div class="section-gap">${panel(`IP matches (${ips.length})`,ips.length?ips.map(r=>`<div class="list-card"><div class="line"><strong class="mono">${esc(r.ip)}</strong><button class="btn btn-small" data-action="open-ip" data-id="${attr(r.ip)}">Inspect →</button></div><p class="panel-note">${num(r.entities.length)} observed entity clusters</p></div>`).join(''):empty())}</div>`}`}
