function download(filename,text,type='text/plain;charset=utf-8'){const blob=new Blob([text],{type}),u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download=filename;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(u),1200);toast(filename+' downloaded locally')}
function reportTxt(id){const a=alert(id),p=profile(id);if(!p)return 'No entity selected';return [`TRACE-X · LOCAL INVESTIGATION BRIEF`,`Dataset: ${state.data?.dataset?.filename||'Bundled synthetic preview'} (${v6Dataset()})`,`Imported SHA-256: ${state.data?.dataset?.sha256||'Demonstration data'}`,`Generated (local browser): ${new Date().toISOString()}`,`Entity: ${id}`,`Relative composite score: ${a?a.composite_score:'Not top-ranked'}`,`Severity bucket: ${a?thresholdTag(a.composite_score):'Not ranked'}`,`Observed IP: ${p.device_ip||'Not present'}`,`Countries: ${(p.countries||[]).join(', ')}`,`Approx incoming: ${p.incoming_total} BTC`,`Approx outgoing: ${p.outgoing_total} BTC`,`Observed counterparties: ${p.n_unique_counterparties}`,`Pattern TXIDs: ${a?JSON.stringify(a.pattern_hits):'Not in alert export'}`,`Score factors: ${a?JSON.stringify(a.score_breakdown):'Not in alert export'}`,`Indicators: ${(p.suspicion_flags||[]).join('; ')}`,``, `LIMITATIONS: ${state.data?.dataset?.warning||'Synthetic preview may use ground-truth-based seeds.'} Composite scores are not crime probabilities. Inferred wallet associations and aggregated flows do not prove exact provenance, ownership, or guilt. Confirm findings with independent evidence.`].join('\n')}
function reportsPage(){const id=state.reportEntity,p=profile(id),a=alert(id);return head('Reports','Generate case briefs and export evidence locally. Report files do not leave this computer.')+`<div class="panel-row">${panel('Create an investigation report',`<label class="field">Report entity<select id="reportEntity" class="select">${optionsEntities(id)}</select></label><div class="section-gap">${p?entityDetail(id):empty('Select an entity to generate a case brief.')}</div><div class="actions section-gap"><button class="btn btn-primary" data-action="report-text">↓ Download case brief</button><button class="btn" data-action="report-json">↓ Download entity JSON</button><button class="btn" data-action="print">Print preview</button></div>`)}${panel('Export datasets',`<p class="panel-note">All exports are generated from the loaded dashboard_data.json file.</p><div class="list-card"><div class="line"><div><strong>Ranked alerts</strong><p class="panel-note">${A().length} entities · CSV</p></div><button class="btn" data-action="csv">Download</button></div></div><div class="list-card"><div class="line"><div><strong>ML transaction scores</strong><p class="panel-note">${M().length} transactions · CSV</p></div><button class="btn" data-action="ml-csv">Download</button></div></div><div class="list-card"><div class="line"><div><strong>Full dashboard export</strong><p class="panel-note">JSON · ${state.source}</p></div><button class="btn" data-action="full-json">Download</button></div></div><div class="note">Reports are suitable for investigative triage and demonstration. They are not independently verified findings or forensic-chain-of-custody packages.</div>`)}</div><div class="section-gap">${panel('Printable case brief',`<pre style="white-space:pre-wrap;font-size:12px;line-height:1.65;font-family:ui-monospace,monospace;max-height:480px;overflow:auto">${esc(reportTxt(id))}</pre>`)}</div>`}
function settingsPage(){return head('Settings','Local display preferences. Changing a threshold filters the UI; it does not retrain or rescore the backend model.')+`<section class="panel"><div class="setting"><div><strong>Appearance</strong><p>Choose a dark or light investigator workspace.</p></div><select class="select" id="settingTheme"><option value="dark" ${settings.theme==='dark'?'selected':''}>Dark</option><option value="light" ${settings.theme==='light'?'selected':''}>Light</option></select></div><div class="setting"><div><strong>Visible graph neighbors</strong><p>Show the strongest incoming and outgoing links without a hairball.</p></div><select class="select" id="settingNeighbors">${[3,4,6,8,10].map(n=>`<option value="${n}" ${settings.neighbors===n?'selected':''}>${n} per side</option>`).join('')}</select></div><div class="setting"><div><strong>ML outlier threshold</strong><p>Controls the number of transactions shown as unusually scored.</p></div><select class="select" id="settingThreshold">${[.5,.6,.7,.8,.9,.95].map(n=>`<option value="${n}" ${settings.threshold===n?'selected':''}>${n}</option>`).join('')}</select></div><div class="setting"><div><strong>Critical composite-score threshold</strong><p>Controls the UI severity label, not a calibrated crime probability.</p></div><select class="select" id="settingCritical">${[.4,.5,.6,.7].map(n=>`<option value="${n}" ${settings.critical===n?'selected':''}>${n}</option>`).join('')}</select></div><div class="setting"><div><strong>Display node labels</strong><p>Show readable truncated wallet/entity identifiers.</p></div><input type="checkbox" id="settingLabels" ${settings.labels?'checked':''}></div><div class="setting"><div><strong>Data source</strong><p class="mono">${esc(state.source)} · ${num(M().length)} transactions</p></div><button class="btn" data-action="reload">⟳ Reload JSON</button></div><div class="section-gap"><button class="btn btn-red" data-action="reset-settings">Reset preferences</button></div></section>`}
function onAction(action,id){if(v7Action(action,id))return;if(v6Action(action,id))return;if(v5Action(action,id))return;switch(action){case 'severity-pick':state.severity=id;state.entity=A().find(a=>thresholdTag(a.composite_score)===id)?.entity_id||A()[0]?.entity_id||state.entity;if(id==='all')state.entity=A()[0]?.entity_id||state.entity;state.caseTx='';render();break;case 'graph-mode':v5Stop();state.graphMode=id;state.zoom=1;render();break;case 'select-case-tx':state.caseTx=id;render();break;case 'nav':if(id!=='replay')v5Stop();navigate(id);$('sidebarNav').closest('.sidebar').classList.remove('open');break;case 'open-alert':if(state.entity!==id)v5SelectEntity(id);state.entity=id;state.caseTx='';navigate('alerts');break;case 'select-entity':v5SelectEntity(id);render();break;case 'graph-node':state.selectedNode=id;if(profile(id)){if(state.entity!==id)v5SelectEntity(id);state.entity=id;state.zoom=1}render();break;case 'focus-graph':pickedEntity(id);break;case 'open-report':state.reportEntity=id;navigate('reports');break;case 'select-ip':state.ip=id;render();break;case 'open-ip':state.ip=id;navigate('network');break;case 'search-value':case 'find-tx':state.query=id;state.searchMode='all';navigate('search');break;case 'zoom-in':state.zoom=Math.min(1.7,Math.round((state.zoom+.2)*10)/10);render();break;case 'zoom-out':state.zoom=Math.max(.6,Math.round((state.zoom-.2)*10)/10);render();break;case 'zoom-reset':state.zoom=1;render();break;case 'trace':state.pathResult=tracePath(state.pathSource,state.pathTarget)||false;render();break;case 'reload':loadData(true);break;case 'png-help':toast('Choose a layer view, select a node, zoom, or trace a directed path.');break;case 'open-evidence':if(state.entity!==id)v5SelectEntity(id);state.entity=id;state.caseTx='';state.selectedNode=id;state.graphMode='evidence';state.zoom=1;navigate('graph');break;case 'dashboard-report':state.reportEntity=state.entity;navigate('reports');break;case 'fullscreen-graph':{const graph=document.querySelector('.graph-canvas');if(!graph){toast('Open the graph first');break}if(document.fullscreenElement){document.exitFullscreen?.()}else if(graph.requestFullscreen){graph.requestFullscreen().catch(()=>toast('Fullscreen is unavailable in this browser'))}else toast('Fullscreen is unavailable in this browser');break}case 'reset-settings':settings={...DEFAULTS};save();render();toast('Local preferences reset');break;case 'csv':csvDownload('tracex_alerts.csv',[['rank','entity_id','composite_score','severity','pattern_txids'],...A().map(a=>[a.rank,a.entity_id,a.composite_score,thresholdTag(a.composite_score),JSON.stringify(a.pattern_hits)])]);break;case 'ml-csv':csvDownload('tracex_ml_scores.csv',[['txid','timestamp','anomaly_score','iso_score','ae_score','entity_id'],...M().map(t=>[t.txid,t.timestamp,t.anomaly_score,t.iso_score,t.ae_score,t.entity_id])]);break;case 'full-json':download('tracex_dashboard_export.json',JSON.stringify(state.data,null,2),'application/json');break;case 'report-text':download(`tracex_case_${state.reportEntity}.txt`,reportTxt(state.reportEntity));break;case 'report-json':download(`tracex_entity_${state.reportEntity}.json`,JSON.stringify({entity_id:state.reportEntity,profile:profile(state.reportEntity),alert:alert(state.reportEntity),limitations:state.data?.dataset?.warning||'Synthetic preview; no exact UTXO provenance'},null,2),'application/json');break;case 'print':window.print();break;default:break}}
document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(!el)return;onAction(el.dataset.action,el.dataset.id)});
document.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches('.graph-node,.case-row')){e.preventDefault();onAction(e.target.matches('.case-row')?'select-case-tx':'graph-node',e.target.dataset.id)}});
document.addEventListener('change',e=>{const el=e.target;switch(el.id){case 'severityFilter':state.severity=el.value;break;case 'graphEntity':if(state.entity!==el.value)v5SelectEntity(el.value);state.entity=el.value;state.zoom=1;state.selectedNode=el.value;break;case 'graphMode':state.graphMode=el.value;state.zoom=1;break;case 'entitySort':state.sort=el.value;break;case 'pathSource':state.pathSource=el.value;state.pathResult=null;break;case 'pathTarget':state.pathTarget=el.value;state.pathResult=null;break;case 'patternFilter':state.pattern=el.value;break;case 'riskEntity':state.entity=el.value;break;case 'reportEntity':state.reportEntity=el.value;break;case 'searchMode':state.searchMode=el.value;break;case 'settingTheme':settings.theme=el.value;break;case 'settingNeighbors':settings.neighbors=Number(el.value);break;case 'settingThreshold':settings.threshold=Number(el.value);break;case 'settingCritical':settings.critical=Number(el.value);break;case 'settingLabels':settings.labels=el.checked;break;default:return}render()});
document.addEventListener('input',e=>{if(['alertQuery','entityQuery'].includes(e.target.id)){const pos=e.target.selectionStart;const id=e.target.id;if(id==='alertQuery')state.alertQuery=e.target.value;else state.query=e.target.value;render();const n=$(id);if(n){n.focus();n.setSelectionRange(pos,pos)}}});
document.addEventListener('submit',e=>{if(!['globalSearch','searchForm'].includes(e.target.id))return;e.preventDefault();state.query=(e.target.id==='globalSearch'?$('globalSearchInput')?.value:$('searchQuery')?.value)||'';if(e.target.id==='globalSearch')state.searchMode='all';navigate('search')});
$('refreshButton').addEventListener('click',()=>loadData(true));$('mobileNav').addEventListener('click',()=>document.querySelector('.sidebar').classList.toggle('open'));window.addEventListener('hashchange',render);save();document.addEventListener('tracex-v7-ready',()=>loadData(),{once:true});

/* TRACE-X v4 – evidence-led views. Works entirely from the local dashboard export. */
const displayStamp=s=>esc(String(s||'Unknown').replace('T',' ').slice(0,19));
const featureNames={pattern_hits:'Structural pattern evidence',risk_score:'Seed-proximity propagation',anomaly_score:'ML anomaly signal',fusion_evidence:'Network correlation'};
const patternNames={peeling_chain:'Peeling chain',fan_out:'Fan-out',consolidation:'Consolidation'};
const caseTxIds=a=>[...new Set(Object.values(a?.pattern_hits||{}).flat())];
const topFactor=a=>(a?.score_breakdown||[]).slice().sort((x,y)=>Number(y.contribution)-Number(x.contribution))[0];
function factorExplainer(f){const k=f.feature;return {pattern_hits:'Structural detector matches in the exported transaction graph; review the flagged TXIDs below.',risk_score:state.data?.dataset?'Not configured for uploaded data; independent seed evidence is not supplied.':'A propagation score reflecting graph proximity to configured seeds. This synthetic demonstration may use ground-truth-labelled seeds.',anomaly_score:'An ensemble outlier score from Isolation Forest and a reconstruction model; unusualness is not a crime probability.',fusion_evidence:'Observed IP or network correlations. Shared infrastructure is not proof of wallet ownership.'}[k]||'A normalized input to the composite triage score.'}
function caseTxRows(a,limit=5){const edges=a?.graph?.tx_edges||[],flag=new Set(caseTxIds(a));const ranked=edges.slice().sort((x,y)=>(Number(flag.has(y.txid))-Number(flag.has(x.txid)))||(Number(y.amount)-Number(x.amount)));const chosen=[],seen=new Set();for(const e of ranked){const key=[e.txid,e.source,e.target].join('|');if(seen.has(key))continue;seen.add(key);chosen.push(e);if(chosen.length>=limit)break}return chosen.sort((x,y)=>String(x.timestamp||'').localeCompare(String(y.timestamp||'')))}
function evidenceTransactionSvg(a,limit=4){let rows=caseTxRows(a,limit),flags=new Set(caseTxIds(a));if(!rows.length)return empty('This alert has no transaction edges in the exported sample. Review its score factors and source TXIDs.');let height=rows.length*97+52;let svg=`<svg class="case-svg" viewBox="0 0 980 ${height}" xmlns="http://www.w3.org/2000/svg" role="img" aria-label="Observed sampled transactions: source wallet to TXID to output wallet"><defs><marker id="v4-arr" markerWidth="8" markerHeight="8" refX="7" refY="4" orient="auto"><path d="M0 0L8 4L0 8Z" fill="#6bbcf4"/></marker></defs><text x="128" y="23" class="case-axis">SOURCE WALLET</text><text x="490" y="23" class="case-axis">TRANSACTION EVENT</text><text x="846" y="23" class="case-axis">OUTPUT WALLET</text>`;
 rows.forEach((e,i)=>{const y=71+i*97,isFlag=flags.has(e.txid),chosen=state.caseTx===e.txid;svg+=`<g data-action="select-case-tx" data-id="${attr(e.txid)}" class="case-row ${chosen?'selected':''}" role="button" tabindex="0"><title>${esc(e.source)} → ${esc(e.txid)} → ${esc(e.target)} · ${esc(btc(e.amount))} · ${displayStamp(e.timestamp)}</title><rect x="8" y="${y-35}" width="964" height="73" rx="12" class="case-row-bg"/><path d="M253 ${y} H395 M584 ${y} H726" class="case-link" marker-end="url(#v4-arr)"/><rect x="27" y="${y-23}" width="226" height="46" rx="9" class="case-wallet"/><text x="140" y="${y+4}" class="case-node-label">${esc(short(e.source,24))}</text><rect x="395" y="${y-23}" width="189" height="46" rx="9" class="case-tx ${isFlag?'pattern-match':''}"/><text x="490" y="${y-1}" class="case-node-label">${esc(e.txid)}</text><text x="490" y="${y+14}" class="case-node-small">${isFlag?'STRUCTURAL MATCH':'OBSERVED EVENT'}</text><rect x="726" y="${y-23}" width="226" height="46" rx="9" class="case-wallet"/><text x="839" y="${y+4}" class="case-node-label">${esc(short(e.target,24))}</text><text x="325" y="${y-11}" class="case-link-label">${esc(btc(e.amount))}</text><text x="655" y="${y+25}" class="case-link-label">${displayStamp(e.timestamp)}</text></g>`});return `<div class="case-viewport">${svg}</svg></div><p class="panel-note">Each row is a sampled wallet → TXID → wallet record. Rows do not establish that funds in one transaction funded another. Click an event to inspect its details.</p>`}
function evidenceTxDetail(a){let rows=a?.graph?.tx_edges||[];let match=rows.find(x=>x.txid===state.caseTx)||caseTxRows(a,1)[0];if(!match)return empty('No exported transaction event.');let flag=caseTxIds(a).includes(match.txid);return `<div class="evidence-event"><div class="line"><strong class="mono">${esc(match.txid)}</strong>${flag?tag('PATTERN MATCH'):tag('SAMPLED TX')}</div>${detailKV('Recorded time',displayStamp(match.timestamp))}${detailKV('Amount',btc(match.amount))}${detailKV('Source',`<span class="mono">${esc(match.source)}</span>`)}${detailKV('Destination',`<span class="mono">${esc(match.target)}</span>`)}<div class="actions section-gap"><button class="btn btn-small" data-action="find-tx" data-id="${attr(match.txid)}">Search TXID →</button></div></div>`}
const detailKV=(name,value)=>`<div class="case-detail-row"><span>${esc(name)}</span><span>${value}</span></div>`;
function caseScorecard(a){const factors=(a.score_breakdown||[]).slice().sort((x,y)=>Number(y.contribution)-Number(x.contribution));return `<div class="case-score-head"><div><small>RELATIVE COMPOSITE SCORE</small><strong>${Number(a.composite_score).toFixed(4)} <span>/ 1.0000</span></strong><p>UI category: ${tag(thresholdTag(a.composite_score))}</p></div><div class="case-rank">#${num(a.rank)}<small>TRIAGE RANK</small></div></div>${factors.map(f=>`<div class="case-factor"><div class="line"><b>${esc(featureNames[f.feature]||f.feature)}</b><strong>+${Number(f.contribution).toFixed(4)}</strong></div><div class="case-factor-track"><span style="width:${Math.max(0,Math.min(100,Number(f.contribution)*100))}%"></span></div><p>${esc(factorExplainer(f))}</p></div>`).join('')}<p class="panel-note">Displayed contributions should sum to the exported composite score (subject to rounding). They are not SHAP values, certainty, or a probability of guilt.</p>`}
function caseNarrative(a){let f=topFactor(a),patterns=Object.entries(a.pattern_hits||{}).filter(([k,ids])=>ids?.length);let p=profile(a.entity_id);return `<div class="case-why"><span class="case-eyebrow">WHY THIS ALERT IS ${esc(thresholdTag(a.composite_score))}</span><h3>${esc(f?featureNames[f.feature]||f.feature:'Composite investigation signals')}</h3><p>The largest recorded score contribution is <strong>+${Number(f?.contribution||0).toFixed(4)}</strong> from ${esc(f?featureNames[f.feature].toLowerCase():'the available signals')}. This contributes to a total score of ${Number(a.composite_score).toFixed(4)}. The severity is a configurable UI threshold, not a confirmed illicit classification.</p>${patterns.length?`<p><b>Detected pattern(s):</b> ${patterns.map(([k,ids])=>`${esc(patternNames[k]||k)} (${ids.length} TXID${ids.length===1?'':'s'})`).join('; ')}.</p>`:'<p>No structural pattern TXID appears in this alert; investigate its model, graph, and network signals.</p>'}${p?.suspicion_flags?.length?`<div class="case-flags">${p.suspicion_flags.map(f=>`<span>${esc(f)}</span>`).join('')}</div>`:''}</div>`}
function caseInvestigation(a){const id=a.entity_id;let flags=caseTxIds(a),sample=new Set((a.graph?.tx_edges||[]).map(e=>e.txid));return `<div class="case-heading"><div><span class="case-eyebrow">INVESTIGATION DOSSIER · ENTITY</span><h2 class="mono">${esc(id)}</h2><p>Wallets: ${num(a.n_wallets_total||a.graph?.wallet_nodes?.filter(x=>x.is_entity_wallet).length||0)} · ${num(a.graph?.tx_edges?.length||0)} sampled transaction edges</p></div><div class="actions"><button class="btn" data-action="open-report" data-id="${attr(id)}">Case report ↗</button><button class="btn btn-primary" data-action="open-evidence" data-id="${attr(id)}">Open transaction lab →</button><button class="btn" data-action="v5-open" data-id="${attr(id)}">▶ Replay evidence</button><button class="btn" data-action="v6-case-new" data-id="${attr(id)}">+ Create case</button><button class="btn" data-action="nav" data-id="provenance">UTXO provenance ↗</button></div></div>
 <div class="case-columns"><section class="case-block">${caseNarrative(a)}${caseScorecard(a)}</section><section class="case-block"><h3>Supporting pattern TXIDs</h3>${flags.length?flags.map(t=>`<div class="case-txid"><span class="mono">${esc(t)}</span>${sample.has(t)?tag('IN SAMPLE'):tag('NOT SAMPLED')}<button class="btn btn-small" data-action="find-tx" data-id="${attr(t)}">Find →</button></div>`).join(''):'<p class="panel-note">No flagged pattern TXID. See other scoring signals.</p>'}<p class="panel-note">A flagged TXID can be absent from the graph preview because the backend exports a limited wallet-edge sample; absence here is not evidence it did not occur.</p><h3 class="section-gap">Model feature deviations</h3>${a.ml_feature_evidence?.features?.length?`<p class="panel-note">Illustrative reconstruction deviations for the most anomalous associated TXID <span class="mono">${esc(a.ml_feature_evidence.txid)}</span> (score ${Number(a.ml_feature_evidence.anomaly_score).toFixed(3)}). These describe unusual inputs to the model; they are not SHAP attributions or evidence of an offense.</p>${a.ml_feature_evidence.features.map(f=>detailKV(esc(f.feature.replaceAll('_',' ')),esc(Number(f.value).toFixed(4))+' '+esc(f.metric.replaceAll('_',' ')))).join('')}`:empty('Feature-level ML deviations unavailable for this dataset.')}<h3 class="section-gap">Recent observed activity</h3>${(a.timeline||[]).slice(-6).reverse().map(t=>detailKV(esc(t.date),`${num(t.count)} recorded event(s)`)).join('')||empty('No timeline provided.')}</section></div>
 <section class="case-block case-evidence"><div class="line"><div><h3>What happened — recorded transaction evidence</h3><p class="panel-note">Actual sampled wallet–transaction–wallet records, with time, amount, and TXID.</p></div><button class="btn btn-small" data-action="open-evidence" data-id="${attr(id)}">Full evidence →</button></div>${evidenceTransactionSvg(a,4)}${evidenceTxDetail(a)}<div class="actions section-gap"><button class="btn btn-primary" data-action="v5-open" data-id="${attr(id)}">▶ Replay this investigation →</button></div></section>`}
function alertListCard(a){const flags=caseTxIds(a);return `<button type="button" class="alert-case ${a.entity_id===state.entity?'active':''}" data-action="open-alert" data-id="${attr(a.entity_id)}"><div class="line"><span class="mono">#${num(a.rank)} · ${esc(a.entity_id)}</span>${tag(thresholdTag(a.composite_score))}</div><div class="line"><strong>${Number(a.composite_score).toFixed(4)}</strong><span class="small">${flags.length?`${flags.length} structural TXID(s)`:'Model / graph signals'}</span></div><p>${esc(topFactor(a)?featureNames[topFactor(a).feature]:'Review exported evidence')}</p></button>`}
function alertsPage(){const q=state.alertQuery.toLowerCase(),items=A().filter(a=>(state.severity==='all'||thresholdTag(a.composite_score)===state.severity)&&(!q||a.entity_id.toLowerCase().includes(q)||Object.keys(a.pattern_hits||{}).join(' ').toLowerCase().includes(q)));const selected=items.find(a=>a.entity_id===state.entity)||items[0];const severity=['all','CRITICAL','HIGH','MEDIUM','LOW'];return head('Alert investigation center','Select a severity and inspect exactly which exported factors, transactions, and observations led to each ranked alert.',`<button class="btn" data-action="csv">↓ Export ranked alerts</button>`)+`<div class="severity-tabs">${severity.map(s=>`<button class="severity-tab ${state.severity===s?'active':''}" data-action="severity-pick" data-id="${s}">${s==='all'?'All alerts':s} <b>${s==='all'?A().length:A().filter(a=>thresholdTag(a.composite_score)===s).length}</b></button>`).join('')}</div><div class="case-workspace"><aside class="panel case-queue"><div class="line"><h2>Investigation queue</h2><span class="panel-note">${items.length} matches</span></div><input class="input" id="alertQuery" value="${attr(state.alertQuery)}" placeholder="Search entity or pattern…" aria-label="Search alerts">${items.length?items.map(alertListCard).join(''):empty('No alerts match this filter. Choose All alerts.')}</aside><div class="case-main">${selected?caseInvestigation(selected):empty('Select an alert to examine its evidence.')}</div></div>`}
function dashboardFlowSvg(id){const incoming=E().filter(e=>e.to===id&&e.from!==id).sort((a,b)=>Number(b.total_amount)-Number(a.total_amount)).slice(0,3);const outgoing=E().filter(e=>e.from===id&&e.to!==id).sort((a,b)=>Number(b.total_amount)-Number(a.total_amount)).slice(0,3);const centerY=210;let s=`<svg class="overview-svg" viewBox="0 0 980 425" role="img" aria-label="Summary of three main sources and destinations of ${attr(id)}" xmlns="http://www.w3.org/2000/svg"><defs><marker id="overview-arrow" markerWidth="8" markerHeight="8" refX="7" refY="4" orient="auto"><path d="M0 0L8 4L0 8Z" fill="#55b7ed"/></marker><linearGradient id="focal" x2="1" y2="1"><stop stop-color="#2078bb"/><stop offset="1" stop-color="#15476d"/></linearGradient></defs><text x="144" y="36" class="overview-heading">TOP INCOMING ENTITIES</text><text x="490" y="36" class="overview-heading">FOCUSED ENTITY</text><text x="836" y="36" class="overview-heading">TOP OUTGOING ENTITIES</text>`;
 const yc=n=>n===1?[210]:n===2?[137,283]:[97,210,323];
 incoming.forEach((e,i)=>{const y=yc(incoming.length)[i];s+=`<path d="M249 ${y} C340 ${y} 365 ${centerY} 421 ${centerY}" class="overview-edge" marker-end="url(#overview-arrow)"/><text x="320" y="${(y+centerY)/2-13}" class="overview-amount">${esc(Number(e.total_amount).toFixed(2))} BTC</text>${overviewNode(e.from,35,y,214,'#153f60',e.tx_count)}`});
 outgoing.forEach((e,i)=>{const y=yc(outgoing.length)[i];s+=`<path d="M558 ${centerY} C630 ${centerY} 640 ${y} 730 ${y}" class="overview-edge" marker-end="url(#overview-arrow)"/><text x="648" y="${(y+centerY)/2-13}" class="overview-amount">${esc(Number(e.total_amount).toFixed(2))} BTC</text>${overviewNode(e.to,730,y,214,'#153f60',e.tx_count)}`});s+=overviewNode(id,421,centerY,137,'url(#focal)',null,true);return s+'</svg>'}
function overviewNode(id,x,y,w,color,n,focus=false){return `<g class="overview-node ${focus?'focal':''}" data-action="graph-node" data-id="${attr(id)}" role="button" tabindex="0"><title>Inspect ${esc(id)}</title><rect x="${x}" y="${y-29}" width="${w}" height="58" rx="11" fill="${color}" stroke="${focus?'#70ceff':'#37698b'}" stroke-width="${focus?2:1}"/><text x="${x+w/2}" y="${y-4}" class="overview-node-name">${esc(id)}</text><text x="${x+w/2}" y="${y+13}" class="overview-node-detail">${focus?'INVESTIGATED':`${num(n)} tx observation(s)`}</text></g>`}
function dashboardPage(){const id=state.entity, p=profile(id),a=alert(id);return `<div class="hero-heading"><div><h1>TRACE-X · Bitcoin Investigation Overview</h1><p>High-level triage of active local blockchain and network metadata</p></div><div class="hero-actions"><button class="btn btn-small" data-action="csv">↓ Export CSV</button><button class="btn btn-primary btn-small" data-action="dashboard-report">Generate report</button></div></div>${heroMetrics()}<div class="v4-overview-grid"><section class="panel v4-overview-main"><div class="panel-head"><div><h2>Money-flow summary</h2><p class="panel-note">The top three observed incoming and outgoing aggregate entity links. Not the full graph.</p></div><div class="actions"><button class="btn btn-small" data-action="open-evidence" data-id="${attr(id)}">Investigate flow →</button><button class="btn btn-small btn-primary" data-action="v5-open" data-id="${attr(id)}">▶ Replay</button></div></div><div class="overview-canvas">${dashboardFlowSvg(id)}</div><div class="flow-readout"><span><b>${esc(id)}</b> · Focused cluster</span><span>↓ ${p?btc(p.incoming_total):'—'} approximate incoming</span><span>↑ ${p?btc(p.outgoing_total):'—'} approximate outgoing</span></div><p class="panel-note">Select a node to refocus. Lines summarize associated transfers, not a validated UTXO provenance chain.</p></section><aside class="panel v4-overview-aside"><div class="panel-head"><h2>Focused investigation</h2>${a?tag(thresholdTag(a.composite_score)):''}</div>${entityDetail(id,true)}<div class="actions section-gap"><button class="btn btn-primary" data-action="open-alert" data-id="${attr(id)}">Why flagged? →</button><button class="btn" data-action="open-evidence" data-id="${attr(id)}">Transaction lab ↗</button></div></aside></div><div class="dashboard-bottom">${panel('⚑ Top alerts',alertMini(),`<button class="btn btn-small btn-ghost" data-action="nav" data-id="alerts">Investigate →</button>`)}${panel('⌁ Detected patterns',patternMini(),`<button class="btn btn-small btn-ghost" data-action="nav" data-id="patterns">Explore →</button>`)}${panel('◉ Risk distribution',riskMini(),`<button class="btn btn-small btn-ghost" data-action="nav" data-id="risk">Details →</button>`)}</div><div class="note hero-footnote">Summary intentionally differs from the dedicated Transaction Graph page: open the lab to explore sampled TXID evidence, multi-hop paths, or alternate entity views. ${esc(state.data?.dataset?.warning || 'Synthetic preview: demonstration labels may influence propagation scores.')}</div>`}
function transactionGraphPage(){const id=state.entity,a=alert(id),modes=[['evidence','Transaction evidence'],['flow','Entity counterparties'],['layered','Multi-hop research'],['replay','Replay timeline']];let view=state.graphMode==='replay'?v5Player(a,false):state.graphMode==='evidence'?(a?`<div class="lab-section">${evidenceTransactionSvg(a,7)}${evidenceTxDetail(a)}</div>`:empty('Sampled transaction evidence is available for ranked alerts. Select a ranked entity.')):graphLayout(id);let path=state.pathResult?`<div class="mini-path">${state.pathResult.map((v,i)=>`${i?' → ':''}<button class="path-chip clickable" data-action="focus-graph" data-id="${attr(v)}">${esc(v)}</button>`).join('')}</div>`:state.pathResult===false?empty('No directed path within five hops in the current inferred graph.'):'<p class="panel-note">Select source and destination, then trace.</p>';return head('Transaction investigation lab','Explore specific sampled TXID evidence, direct entity relationships, or multi-hop hypotheses — independently of the dashboard overview.',`<button class="btn" data-action="open-report" data-id="${attr(id)}">Case report ↗</button>`)+`<div class="panel lab-panel"><div class="lab-controls"><label class="field">Investigated entity<select id="graphEntity" class="select">${optionsEntities(id)}</select></label><div class="lab-tabs">${modes.map(([mode,name])=>`<button class="btn ${state.graphMode===mode?'btn-primary':''}" data-action="graph-mode" data-id="${mode}">${name}</button>`).join('')}</div></div><div class="lab-explainer">${state.graphMode==='evidence'?'Each graph row comes from an exported source wallet, transaction ID, destination wallet, amount, and timestamp. No fake intermediary nodes.':state.graphMode==='flow'?'All displayed lines are direct aggregated entity links. Change the focus or zoom to explore.':state.graphMode==='replay'?'Chronological event replay of exported TXIDs; adjacent events are not verified coin transfers.':'Investigative multi-hop layout based on observed links. Hop layers do not imply verified criminal roles.'}</div><div class="lab-grid"><div class="lab-stage">${view}</div><aside class="panel lab-side"><h3>Investigation context</h3>${entityDetail(id,true)}${a?`<div class="section-gap">${caseScorecard(a)}</div>`:''}<div class="actions section-gap"><button class="btn btn-primary" data-action="open-alert" data-id="${attr(id)}">Why this score? →</button></div></aside></div></div><div class="section-gap">${panel('Directed entity path tracer',`<div class="form-row"><label class="field">Source entity<select id="pathSource" class="select">${optionsEntities(state.pathSource)}</select></label><label class="field">Destination entity<select id="pathTarget" class="select">${optionsEntities(state.pathTarget)}</select></label><button class="btn btn-primary" data-action="trace">Trace path →</button></div><div class="section-gap">${path}</div><p class="panel-note">Breadth-first traversal of inferred aggregate entity relationships, maximum five hops. A path does not establish the same coins or common ownership.</p>`)}</div>`}
function graphPage(){return transactionGraphPage()}


/* TRACE-X v5 — offline fund-tracing & chronological event replay.
 * Only renders fields actually included in the local export. No invented UTXO provenance. */
let v5Playback=null;
const v5Stop=()=>{if(v5Playback!==null){clearInterval(v5Playback);v5Playback=null}state.replayPlaying=false};
function v5SelectEntity(id){v5Stop();state.entity=id;state.selectedNode=id;state.replayIndex=0;state.replayFilter='all';state.pathResult=null}
function v5Events(a){
 if(!a)return [];
 const recordMap=new Map(M().map(t=>[String(t.txid),t]));
 const groups=new Map();const flags=new Set(caseTxIds(a));
 for(const row of a.graph?.tx_edges||[]){
  const id=String(row.txid||'');if(!id)continue;
  if(!groups.has(id))groups.set(id,{txid:id,rows:[],record:recordMap.get(id)||null,pattern:flags.has(id),sampled:true,timestamp:row.timestamp||'',missing:false});
  const g=groups.get(id),key=[row.source,row.target,row.amount,row.timestamp].join('|');
  if(!g.rows.some(x=>[x.source,x.target,x.amount,x.timestamp].join('|')===key))g.rows.push(row);
  if(row.timestamp&&(!g.timestamp||String(row.timestamp)<g.timestamp))g.timestamp=row.timestamp;
 }
 for(const id of flags){if(groups.has(String(id)))continue;const rec=recordMap.get(String(id))||null;
  groups.set(String(id),{txid:String(id),rows:[],record:rec,pattern:true,sampled:false,timestamp:rec?.timestamp||'',missing:!rec});}
 return [...groups.values()].sort((x,y)=>{
  if(!x.timestamp)return 1;if(!y.timestamp)return -1;
  return String(x.timestamp).localeCompare(String(y.timestamp))||x.txid.localeCompare(y.txid);
 });
}
const v5Filtered=()=>{const ev=v5Events(alert(state.entity));return state.replayFilter==='flagged'?ev.filter(e=>e.pattern):ev};
function v5Chosen(events){const seq=events||v5Filtered();if(!seq.length)return null;state.replayIndex=Math.max(0,Math.min(state.replayIndex||0,seq.length-1));return seq[state.replayIndex]}
const v5Field=(label,val)=>`<div class="v5-field"><span>${esc(label)}</span><strong>${esc(val)}</strong></div>`;
function v5EventSvg(ev){if(!ev)return empty('No transaction records for this entity in the current export.');if(ev.missing)return `<div class="v5-unavailable">${esc(ev.txid)} is flagged by a structural detector but is absent from both the sampled evidence graph and the transaction record export. No transfer graph can be shown without the underlying record.</div>`;
 const rows=ev.rows.slice(0,3),rec=ev.record,synthetic=!ev.sampled;
 const displayed=rows.length?rows:[{source:(rec?.from_wallets||[]).length===1?rec.from_wallets[0]:`${rec?.from_wallets?.length||0} input addresses`,target:(rec?.to_wallets||[]).length===1?rec.to_wallets[0]:`${rec?.to_wallets?.length||0} output addresses`,amount:rec?.amount,timestamp:rec?.timestamp}];
 let svg=`<svg class="v5-event-svg" viewBox="0 0 970 ${55+displayed.length*99}" xmlns="http://www.w3.org/2000/svg" role="img" aria-label="Recorded transaction event ${attr(ev.txid)}"><defs><marker id="v5-tip" markerWidth="8" markerHeight="8" refX="7" refY="4" orient="auto"><path d="M0 0L8 4L0 8Z" fill="#62bfff"/></marker></defs><text x="130" y="25" class="v5-svg-title">${synthetic?'INPUT SET':'OBSERVED SOURCE'}</text><text x="485" y="25" class="v5-svg-title">TRANSACTION ID</text><text x="842" y="25" class="v5-svg-title">${synthetic?'OUTPUT SET':'OBSERVED DESTINATION'}</text>`;
 displayed.forEach((r,i)=>{const y=77+i*99;svg+=`<rect x="8" y="${y-31}" width="954" height="70" rx="11" fill="${ev.pattern?'#30212e':'#122b40'}" stroke="${ev.pattern?'#834958':'#33536e'}"/><path d="M263 ${y} H375 M588 ${y} H707" stroke="#62bfff" stroke-width="2" marker-end="url(#v5-tip)"/><rect x="20" y="${y-23}" width="243" height="47" rx="8" fill="#1a4a67"/><rect x="375" y="${y-23}" width="213" height="47" rx="8" fill="${ev.pattern?'#813948':'#175d8a'}"/><rect x="707" y="${y-23}" width="243" height="47" rx="8" fill="#1a4a67"/><text x="141" y="${y+5}" class="v5-svg-label">${esc(short(r.source,24))}</text><text x="482" y="${y+5}" class="v5-svg-label">${esc(short(ev.txid,23))}</text><text x="828" y="${y+5}" class="v5-svg-label">${esc(short(r.target,24))}</text><text x="319" y="${y-10}" class="v5-svg-caption">${esc(Number.isFinite(Number(r.amount))?btc(r.amount):'Amount unknown')}</text><text x="643" y="${y+25}" class="v5-svg-caption">${displayStamp(r.timestamp||ev.timestamp)}</text>`});
 return `<div class="v5-svg-scroll">${svg}</svg></div><p class="panel-note">${synthetic?'Transaction-level input/output sets; the export cannot establish which input funded any particular output.':'Each row is an exported wallet → transaction → wallet observation. A row is not UTXO-exact provenance.'} ${ev.rows.length>3?`${ev.rows.length-3} more sampled rows not drawn; see details below.`:''}</p>`;
}
function v5EventInspector(ev){if(!ev)return empty('No event selected.');const rec=ev.record;
 return `<div class="v5-event-top"><div><span class="case-eyebrow">EVENT EVIDENCE</span><h3 class="mono">${esc(ev.txid)}</h3></div><span class="badge ${ev.pattern?'high':'safe'}">${ev.pattern?'STRUCTURAL MATCH':'OBSERVED'}</span></div>
 ${v5Field('Recorded timestamp',ev.timestamp?String(ev.timestamp).replace('T',' '):'Not available')}
 ${v5Field('Evidence source',ev.sampled?'Sampled transaction graph':rec?'Full exported transaction metadata':'TXID only — no underlying record')}
 ${v5Field('Wallet-output rows',ev.rows.length)}
 ${rec?v5Field('Transaction-level amount',Number.isFinite(Number(rec.amount))?btc(rec.amount):'Unknown'):''}
 ${rec?v5Field('ML anomaly score',Number.isFinite(Number(rec.anomaly_score))?Number(rec.anomaly_score).toFixed(4):'Unavailable'):''}
 ${rec?v5Field('Isolation Forest',Number.isFinite(Number(rec.iso_score))?Number(rec.iso_score).toFixed(4):'Unavailable'):''}
 ${rec?v5Field('Autoencoder',Number.isFinite(Number(rec.ae_score))?Number(rec.ae_score).toFixed(4):'Unavailable'):''}
 ${!ev.sampled&&rec?`<p class="panel-note">Inputs: ${(rec.from_wallets||[]).map(esc).join(', ')||'Unavailable'}<br>Outputs: ${(rec.to_wallets||[]).map(esc).join(', ')||'Unavailable'}</p>`:''}
 ${ev.rows.length?`<details class="v5-rows"><summary>View ${ev.rows.length} sampled relationship(s)</summary>${ev.rows.slice(0,30).map(e=>`<p class="mono">${esc(short(e.source,20))} → ${esc(short(e.target,20))} · ${esc(btc(e.amount))}</p>`).join('')}${ev.rows.length>30?'<p>Additional observations omitted from this view.</p>':''}</details>`:''}
 <div class="actions section-gap"><button class="btn btn-small" data-action="find-tx" data-id="${attr(ev.txid)}">Search TXID →</button><button class="btn btn-small" data-action="open-alert" data-id="${attr(state.entity)}">Risk explanation →</button></div>`;
}
function v5Timeline(events){if(!events.length)return empty('No replayable records in this export.');const i=Math.max(0,Math.min(state.replayIndex||0,events.length-1));const lo=Math.max(0,i-9),hi=Math.min(events.length,Math.max(20,i+10));return `<div class="v5-timeline" aria-label="Chronological observed events">${events.slice(lo,hi).map((e,j)=>`<button class="v5-tick ${lo+j===i?'selected':''}" data-action="v5-step" data-id="${lo+j}"><span class="v5-seq">${String(lo+j+1).padStart(2,'0')}</span><span class="mono">${esc(short(e.txid,18))}</span><small>${displayStamp(e.timestamp)}</small>${e.pattern?'<b>STRUCTURAL MATCH</b>':''}${e.missing?'<b>NOT EXPORTED</b>':''}</button>`).join('')}</div>`}
function v5Player(a,standalone=true){if(!a)return empty('Select a ranked alert with evidence to replay.');let events=v5Filtered(),ev=v5Chosen(events);const n=events.length,idx=state.replayIndex||0;return `<div class="v5-replay-shell"><div class="v5-topline"><div><span class="case-eyebrow">CHRONOLOGICAL EVIDENCE REPLAY</span><h2>Observed activity · ${esc(a.entity_id)}</h2><p>One recorded TXID per step. Adjacent events are not assumed to transfer the same coins.</p></div><div class="actions"><button class="btn btn-small" data-action="v5-filter" data-id="all" ${state.replayFilter==='all'?'aria-pressed="true"':''}>All ${v5Events(a).length}</button><button class="btn btn-small" data-action="v5-filter" data-id="flagged" ${state.replayFilter==='flagged'?'aria-pressed="true"':''}>Pattern TXIDs ${v5Events(a).filter(x=>x.pattern).length}</button></div></div>
 ${n?`<div class="v5-controls"><button class="btn" data-action="v5-first" aria-label="First event">|◀</button><button class="btn" data-action="v5-prev" aria-label="Previous event" ${idx===0?'disabled':''}>◀</button><button class="btn btn-primary" data-action="v5-play">${state.replayPlaying?'Ⅱ Pause':'▶ Play'}</button><button class="btn" data-action="v5-next" aria-label="Next event" ${idx===n-1?'disabled':''}>▶</button><button class="btn" data-action="v5-last" aria-label="Last event">▶|</button><label>Speed <select id="v5Speed" class="select"><option value="1" ${state.replaySpeed===1?'selected':''}>1×</option><option value="2" ${state.replaySpeed===2?'selected':''}>2×</option><option value="4" ${state.replaySpeed===4?'selected':''}>4×</option></select></label><span class="v5-progress-text">Event ${idx+1} / ${n}</span></div>
 <input id="v5Scrub" class="v5-scrub" aria-label="Replay position" type="range" min="0" max="${Math.max(0,n-1)}" value="${idx}" ${n===1?'disabled':''}>
 ${v5Timeline(events)}<div class="v5-focus-layout"><section class="panel v5-main-event"><div class="v5-section-head"><h3>What was observed at this step?</h3><span class="v5-time">${displayStamp(ev.timestamp)}</span></div>${v5EventSvg(ev)}</section><aside class="panel v5-event-side">${v5EventInspector(ev)}</aside></div>`:empty('No records match this filter. Choose All events.')}
 <div class="note">Evidence boundary: time ordering shows observation timestamps only, not a verified chain of custody, spend linkage, wallet ownership, or illegal activity. For exact tracing, the backend needs UTXO inputs (prev_txid, vout), outputs, and spend relationships.</div></div>`}
function v5CandidateRows(from,to){const p=profile(from);let rows=(p?.outgoing_list||[]).filter(x=>String(x.counterparty)===to&&x.txid);const seen=new Set();rows=rows.filter(r=>{const k=[r.txid,r.timestamp,r.amount].join('|');if(seen.has(k))return false;seen.add(k);return true;});return rows.sort((x,y)=>String(x.timestamp||'').localeCompare(String(y.timestamp||''))).slice(0,4)}
function v5TraceEvidence(){const path=Array.isArray(state.pathResult)?state.pathResult:null;if(!path)return state.pathResult===false?empty('No directed inferred entity route within five hops. Try another pair.'):'<p class="panel-note">Select a source and destination, then click Trace inferred route.</p>';
 if(path.length===1)return `<div class="v5-unavailable">Source and destination are the same entity. Choose two different entities for a route.</div>`;
 const edges=E();let cards=[];
 for(let i=0;i<path.length-1;i++){const from=path[i],to=path[i+1],e=edges.find(x=>x.from===from&&x.to===to),examples=v5CandidateRows(from,to);cards.push(`<article class="v5-hop"><div class="v5-hop-head"><span>HOP ${i+1}</span><b class="mono">${esc(from)} → ${esc(to)}</b></div>${v5Field('Aggregated inferred flow',e?btc(e.total_amount):'Not exported')}${v5Field('Observed count',e?.tx_count??'Unknown')}
 ${examples.length?`<div class="v5-hop-samples"><b>Supporting observed edge samples</b>${examples.map(r=>`<div class="v5-hop-sample"><button data-action="find-tx" data-id="${attr(r.txid)}" class="btn btn-small">${esc(r.txid)} ↗</button><span>${displayStamp(r.timestamp)} · ${esc(btc(r.amount))}</span></div>`).join('')}</div>`:e?.sample_txid?`<p class="panel-note">Example aggregate-edge TXID: <button class="btn btn-small" data-action="find-tx" data-id="${attr(e.sample_txid)}">${esc(e.sample_txid)} ↗</button>${M().find(t=>t.txid===e.sample_txid)?.timestamp?' · '+displayStamp(M().find(t=>t.txid===e.sample_txid).timestamp):' · timestamp unavailable in export'}. This is one example, not proven continuity.</p>`:'<p class="panel-note">No individual supporting TXID was exported for this link.</p>'}</article>`)}
 return `<div class="v5-path-rail">${path.map((id,i)=>`<span class="v5-path-node mono">${esc(id)}</span>${i<path.length-1?'<span class="v5-path-arrow">→</span>':''}`).join('')}</div><div class="v5-hop-grid">${cards.join('')}</div><div class="note">The route is a directed path in an inferred aggregate entity graph. Per-hop examples are separate observations; the export does not prove continuous coin provenance, chronological spend linkage, or ownership identity. Do not add per-hop volumes to estimate funds traced.</div>`;
}
function replayPage(){const id=state.entity,a=alert(id);return head('Fund tracing & replay','Follow observed transaction events chronologically, then inspect a separate inferred entity route.',`<button class="btn" data-action="open-alert" data-id="${attr(id)}">← Alert dossier</button>`)+
 `<div class="v5-summary-strip"><div><small>INVESTIGATED ENTITY</small><strong class="mono">${esc(id||'None')}</strong></div><div><small>COMPOSITE SCORE</small><strong>${a?Number(a.composite_score).toFixed(4):'Not ranked'}</strong></div><div><small>OBSERVED TXID EVENTS</small><strong>${a?v5Events(a).length:0}</strong></div><div><small>PATTERN TXIDs</small><strong>${a?caseTxIds(a).length:0}</strong></div></div>
 <section class="panel"><div class="v5-page-entity"><label class="field">Choose ranked investigation<select id="v5Entity" class="select">${A().map(x=>`<option value="${attr(x.entity_id)}" ${x.entity_id===id?'selected':''}>${esc(x.entity_id)} · ${Number(x.composite_score).toFixed(3)}</option>`).join('')}</select></label><button class="btn" data-action="open-evidence" data-id="${attr(id)}">Transaction lab ↗</button></div></section>
 ${v5Player(a)}<section class="panel v5-trace-panel"><div class="panel-head"><div><h2>Inferred entity route investigator</h2><p class="panel-note">Explore a directed route and inspect recorded sample TXIDs per hop.</p></div></div><div class="v5-trace-controls"><label class="field">From entity<select id="pathSource" class="select">${optionsEntities(state.pathSource)}</select></label><label class="field">To entity<select id="pathTarget" class="select">${optionsEntities(state.pathTarget)}</select></label><button class="btn btn-primary" data-action="v5-trace">Trace inferred route →</button></div>${v5TraceEvidence()}</section>`}
function v5Start(){v5Stop();const events=v5Filtered();if(events.length<2){toast('Not enough events to play');return}if(state.replayIndex>=events.length-1)state.replayIndex=0;state.replayPlaying=true;const speed=state.replaySpeed||1;
 v5Playback=setInterval(()=>{if(state.route!=='replay'&&state.graphMode!=='replay'){v5Stop();return}const ev=v5Filtered();if(state.replayIndex>=ev.length-1){v5Stop();render();return}state.replayIndex++;render()},1500/speed);render();}
function v5Action(action,id){switch(action){
 case 'v5-open':if(id&&id!==state.entity)v5SelectEntity(id);v5Stop();navigate('replay');return true;
 case 'v5-step':v5Stop();state.replayIndex=Math.max(0,Number(id)||0);render();return true;
 case 'v5-first':v5Stop();state.replayIndex=0;render();return true;
 case 'v5-last':v5Stop();state.replayIndex=Math.max(0,v5Filtered().length-1);render();return true;
 case 'v5-next':v5Stop();state.replayIndex=Math.min(v5Filtered().length-1,(state.replayIndex||0)+1);render();return true;
 case 'v5-prev':v5Stop();state.replayIndex=Math.max(0,(state.replayIndex||0)-1);render();return true;
 case 'v5-filter':v5Stop();state.replayFilter=id==='flagged'?'flagged':'all';state.replayIndex=0;render();return true;
 case 'v5-play':if(state.replayPlaying){v5Stop();render()}else v5Start();return true;
 case 'v5-trace':state.pathResult=tracePath(state.pathSource,state.pathTarget)||false;render();return true;
 default:return false;}}

// New controls use a separate delegated listener so the original ten pages remain unchanged.
document.addEventListener('change',e=>{
 const el=e.target;
 if(el.id==='v5Entity'){v5SelectEntity(el.value);state.pathSource=el.value;render()}
 else if(el.id==='v5Speed'){state.replaySpeed=Math.max(1,Math.min(4,Number(el.value)||1));if(state.replayPlaying)v5Start()}
 else if(el.id==='v5Scrub'){v5Stop();state.replayIndex=Math.max(0,Number(el.value)||0);render()}
});
